<?php
declare(strict_types=1);
use VoteTrust\Candidate\Security\ApplicationValidator; use VoteTrust\Candidate\Security\DocumentValidator; use VoteTrust\Candidate\Security\ProfilePhotoValidator; use VoteTrust\Candidate\Services\RealRegistrationService; use VoteTrust\Candidate\Services\RegistrationProxy;
require dirname(__DIR__).'/autoload.php'; require dirname(__DIR__).'/config.php'; session_name('votetrust_candidate'); session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Lax']);
function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');} function token():string{$_SESSION['csrf']??=bin2hex(random_bytes(32));return $_SESSION['csrf'];} function validCsrf():bool{return isset($_POST['_token'],$_SESSION['csrf'])&&hash_equals($_SESSION['csrf'],(string)$_POST['_token']);} function go(string $p='/'):never{header('Location: '.$p,true,303);exit;} function flash(string $t,string $m):void{$_SESSION['flash']=[$t,$m];}
$pdo=candidatePdo(); $path=rtrim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/','/')?:'/';
if ($path === '/profile') { require __DIR__ . '/profile.php'; exit; }
if ($path === '/payment') { require __DIR__ . '/payment.php'; exit; }
if($path==='/candidate-photo'){$s=$pdo->prepare('SELECT profile_photo,profile_photo_mime FROM candidacy WHERE id=?');$s->execute([(int)($_GET['id']??0)]);$p=$s->fetch(PDO::FETCH_ASSOC);$name=is_array($p)?basename((string)$p['profile_photo']):'';$file=candidatePhotoDirectory().'/'.$name;if(!is_file($file))$file=candidateUploadDirectory().'/'.$name;if(!$p||!is_file($file)){http_response_code(404);exit;}header('Content-Type: '.(string)$p['profile_photo_mime']);readfile($file);exit;}
if($path==='/login'&&$_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('SELECT id,password_hash FROM user WHERE username=?');$s->execute([trim((string)$_POST['username'])]);$a=$s->fetch(PDO::FETCH_ASSOC);if(!validCsrf()||!is_array($a)||!password_verify((string)$_POST['password'],(string)$a['password_hash'])){flash('error','Invalid login.');go();}session_regenerate_id(true);$_SESSION['user_id']=(int)$a['id'];go();}
if($path==='/logout'&&$_SERVER['REQUEST_METHOD']==='POST'){if(validCsrf()){$_SESSION=[];session_destroy();}go();}
$user=null;if(isset($_SESSION['user_id'])){$s=$pdo->prepare('SELECT id,username FROM user WHERE id=?');$s->execute([(int)$_SESSION['user_id']]);$user=$s->fetch(PDO::FETCH_ASSOC)?:null;}
if($path==='/apply'&&$_SERVER['REQUEST_METHOD']==='POST'){if(!is_array($user)||!validCsrf())go();try{$docs=[];$u=$_FILES['documents']??[];if(is_array($u)&&is_array($u['name']??null))foreach($u['name'] as $i=>$_)$docs[]=['name'=>$u['name'][$i]??'','tmp_name'=>$u['tmp_name'][$i]??'','error'=>$u['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$u['size'][$i]??0];$service=new RegistrationProxy(new RealRegistrationService($pdo,new DocumentValidator(),new ProfilePhotoValidator(),candidateUploadDirectory()),new ApplicationValidator());$service->apply((int)$user['id'],(int)$_POST['election_id'],$_POST,$docs,is_array($_FILES['profile_photo']??null)?$_FILES['profile_photo']:[]);flash('success','Application submitted with Pending status.');}catch(Throwable $e){flash('error',$e instanceof InvalidArgumentException?$e->getMessage():'Unable to submit application.');}go();}
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Candidate Registration</title><link rel="stylesheet" href="/assets/app.css"></head><body><header><strong>VoteTrust</strong><span>Candidate Registration</span><?php if($user):?><a class="account" href="/profile">My Profile</a><form method="post" action="/logout"><input type="hidden" name="_token" value="<?=e(token())?>"><button>Sign out</button></form><?php endif?></header><main><?php if($flash):?><div class="notice <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif?><?php if(!$user):?><section class="card login"><h1>Candidate sign in</h1><form method="post" action="/login"><input type="hidden" name="_token" value="<?=e(token())?>"><label>Username<input name="username" required></label><label>Password<input type="password" name="password" required></label><button class="primary">Sign in</button></form></section><?php elseif($path==='/profile'):$s=$pdo->prepare('SELECT c.id,c.status,c.position_sought,e.title FROM candidacy c JOIN election e ON e.id=c.election_id WHERE c.candidate_id=? ORDER BY c.registered_at DESC');$s->execute([(int)$user['id']]);$apps=$s->fetchAll(PDO::FETCH_ASSOC);?><h1>My Profile</h1><section class="card"><?php if(!$apps):?>No candidacy application submitted.<?php endif?><?php foreach($apps as $app):?><article class="application"><?php if((int)$app['id']>2):?><img src="/candidate-photo?id=<?=(int)$app['id']?>" alt="Candidate photo"><?php endif?><div><strong><?=e($app['title'])?></strong><span><?=e((string)$app['position_sought'])?></span></div><b><?=e($app['status'])?></b></article><?php endforeach?></section><p><a href="/">Back to application</a></p><?php else:$elections=$pdo->query("SELECT id,title,nomination_end FROM election WHERE status='NOMINATION_OPEN'")->fetchAll(PDO::FETCH_ASSOC);?><h1>Stand for election</h1><?php if(!$elections):?><section class="card">No election is accepting nominations.</section><?php else:?><section class="card"><h2>New application</h2><form method="post" action="/apply" enctype="multipart/form-data"><input type="hidden" name="_token" value="<?=e(token())?>"><label>Election<select name="election_id"><?php foreach($elections as $election):?><option value="<?=$election['id']?>"><?=e($election['title'])?></option><?php endforeach?></select></label><label>Position<input name="position_sought" required></label><label>Manifesto<textarea name="manifesto" minlength="50" required></textarea></label><label>Supporting details<textarea name="supporting_details"></textarea></label><label>Supporting documents<input type="file" name="documents[]" multiple></label><label>Candidate photo<input type="file" name="profile_photo" accept=".jpg,.jpeg,.png" required></label><button class="primary">Submit application</button></form></section><?php endif;endif?></main></body></html>
